#include "MeshBooleanExactKernelFixtures.h"
#include <iostream>
using namespace exact_test;
int main(){try{prng r;for(unsigned i=0;i<300;++i){std::int64_t a=std::int64_t(r.next()%2001)-1000,b=std::int64_t(r.next()%2001)-1000,c=std::int64_t(r.next()%2001)-1000;auto A=big_int(a),B=big_int(b),C=big_int(c);require((A+B)+C==A+(B+C),"integer associativity");auto x=q(a,std::uint64_t(r.next()%31+1)),y=q(b,std::uint64_t(r.next()%31+1));require((x+y)-y==x,"rational inverse");auto p=p2(a,b),u=p2(b,c),v=p2(c,a);require(int(orient2d(p,u,v))==-int(orient2d(p,v,u)),"orientation antisymmetry");}for(std::uint32_t bits: {0U,1U,0x007fffffU,0x00800000U,0x3f7fffffU,0x3f800000U,0x7f7fffffU,0x80000000U}){auto d=decode_coordinate(from_bits<float>(bits));require(d.has_value(),"finite corpus decode");}auto overlap=relate_segments(exact_segment3{p3(0,0,0),p3(4,0,0)},exact_segment3{p3(2,0,0),p3(6,0,0)});require(overlap.dimension==intersection_dimension::segment,"axis-aligned 3D overlap");std::cout<<"PASS exact properties\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
